// openapi-ts.config.ts — codegen config for the Aura REST client.
//
// Regenerate with:  npm run codegen   (or `task codegen` from the repo root)
//
// Input  : openapi/openapi.yaml   (the Aura API spec, OpenAPI 3.1)
// Output : src/generated/         (typed client generated by @hey-api/openapi-ts,
//                                 one typed function per operationId). The
//                                 generated tree is COMMITTED (not gitignored)
//                                 so end users who `pi install` this package
//                                 get a working client without running codegen.
//
// We use @hey-api/openapi-ts@0.99.x. A bare string `input: "openapi/openapi.yaml"`
// is ambiguous in 0.99 — the parser sees `org/project`-shaped text and tries
// to resolve it as a Hey API platform registry shorthand. A leading `./`
// forces file-path interpretation (the parser only routes `org/project`-shaped
// strings through the shorthand resolver).
//
// In the 0.99 plugin model the HTTP client is itself a plugin, so we list it
// explicitly alongside the default @hey-api/typescript + @hey-api/sdk plugins
// (when you set `plugins`, the defaults are no longer added automatically).
//
// --- .js import extensions (tsConfigPath) ---------------------------------
// The generated client's consumers are the `scripts/` bundler resolution
// (moduleResolution: bundler; `scripts/src/aura.ts` imports it through
// `@pi-aura/shared/aura-client` and esbuild bundles the same tree) and
// the shared NodeNext codegen tsconfig `tsconfig.codegen.json` below.
// The extension suites are not consumers: their dynamic-import seam keeps
// the client out of the strip-types path, and the digest-dashboard
// extension whose NodeNext tsconfig once typechecked the tree is gone
// with the removal.
// Under NodeNext, relative import specifiers MUST carry a `.js` extension or
// tsc fails with TS2307/TS2834. openapi-ts reads `output.tsConfigPath` and,
// when the resolved tsconfig has `moduleResolution: "nodenext"`, automatically
// appends `.js` to every generated relative import (the supported mechanism
// since openapi-ts v0.67). We point it at `tsconfig.codegen.json` so the
// generated tree is correct out-of-the-box and survives `npm run codegen`
// runs, with no hand-patching of generated files needed. `.js`-extended
// specifiers also resolve fine under `bundler`, so the shared package's own
// `tsc --noEmit` (bundler) is unaffected.
//
// `tsConfigPath` is resolved relative to the openapi-ts package dir, not the
// config file, so we pass an absolute path derived from `import.meta.url`.

import { defineConfig } from "@hey-api/openapi-ts";
import { fileURLToPath } from "node:url";
import path from "node:path";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

export default defineConfig({
  input: "./openapi/openapi.yaml",
  output: {
    path: "src/generated",
    tsConfigPath: path.resolve(__dirname, "tsconfig.codegen.json"),
  },
  plugins: [
    // TypeScript interfaces for every component schema + request/response.
    "@hey-api/typescript",
    // One typed function per operationId (tree-shakeable, function-based).
    "@hey-api/sdk",
    // Native-fetch HTTP client the SDK functions call into.
    "@hey-api/client-fetch",
  ],
});
